begin;
do $$
declare uid uuid:=gen_random_uuid();other_uid uuid:=gen_random_uuid();prof_uid uuid:=gen_random_uuid();ta uuid;tb uuid;pl uuid;pro uuid;sid uuid;cid uuid;aid uuid;foreign_aid uuid;eid uuid;x jsonb;denied boolean;today date:=(now() at time zone 'America/Sao_Paulo')::date;
begin
 insert into auth.users(id,email,email_confirmed_at) values(uid,'finance-fixture@example.invalid',now()),(other_uid,'finance-other@example.invalid',now()),(prof_uid,'finance-prof@example.invalid',now());
 insert into public.plans(name,amount,months) values('Fixture financeiro',0,1) returning id into pl;
 insert into public.tenants(name,slug,responsible,email) values('Fixture Finance A','finance-fixture-'||substr(uid::text,1,8),'Teste','finance-fixture@example.invalid') returning id into ta;
 insert into public.tenants(name,slug,responsible,email) values('Fixture Finance B','finance-fixture-'||substr(other_uid::text,1,8),'Teste','finance-other@example.invalid') returning id into tb;
 insert into public.licenses(tenant_id,plan_id,starts_on,expires_on) values(ta,pl,today-1,today+30),(tb,pl,today-1,today+30);
 insert into public.memberships(tenant_id,email,user_id,role) values(ta,'finance-fixture@example.invalid',uid,'admin'),(tb,'finance-other@example.invalid',other_uid,'admin'),(ta,'finance-prof@example.invalid',prof_uid,'professional');
 insert into public.services(tenant_id,name,duration,price) values(ta,'Fixture serviço',30,35.50) returning id into sid;
 insert into public.professionals(tenant_id,name) values(ta,'Fixture profissional') returning id into pro;
 insert into public.customers(tenant_id,name,phone) values(ta,'Fixture cliente','24999999999') returning id into cid;
 insert into public.appointments(tenant_id,professional_id,service_id,customer_id,starts_at,ends_at,status,price) values(ta,pro,sid,cid,now(),now()+interval '30 minutes','Concluído',35.50) returning id into aid;
 perform set_config('request.jwt.claim.sub',uid::text,true);
 x:=public.agenda_finance('save',jsonb_build_object('tenant_id',ta,'kind','income','appointment_id',aid,'amount',9999,'due_on',today,'settled_on',today,'payment_method','Pix'));
 eid:=(x->>'id')::uuid;
 if (select amount from public.financial_entries where id=eid)<>35.50 then raise exception 'FAIL server-authoritative appointment amount';end if;
 x:=public.agenda_finance('get',jsonb_build_object('tenant_id',ta,'from',today,'to',today));
 if jsonb_array_length(x->'appointments')<>0 or jsonb_array_length(x->'entries')<>1 then raise exception 'FAIL receipt deduplication';end if;
 denied:=false;begin perform public.agenda_finance('save',jsonb_build_object('tenant_id',ta,'kind','income','appointment_id',aid,'due_on',today));exception when others then denied:=true;end;if not denied then raise exception 'FAIL duplicate receipt';end if;
 denied:=false;begin perform public.agenda_finance('get',jsonb_build_object('tenant_id',tb,'from',today,'to',today));exception when others then denied:=true;end;if not denied then raise exception 'FAIL cross-tenant read';end if;
 perform set_config('request.jwt.claim.sub',other_uid::text,true);
 denied:=false;begin perform public.agenda_finance('void',jsonb_build_object('tenant_id',tb,'id',eid,'version',1));exception when others then denied:=true;end;if not denied then raise exception 'FAIL cross-tenant write';end if;
 denied:=false;begin perform public.agenda_finance('save',jsonb_build_object('tenant_id',tb,'kind','income','appointment_id',aid,'due_on',today));exception when others then denied:=true;end;if not denied then raise exception 'FAIL cross-tenant appointment';end if;
 perform set_config('request.jwt.claim.sub',prof_uid::text,true);
 denied:=false;begin perform public.agenda_finance('get',jsonb_build_object('tenant_id',ta,'from',today,'to',today));exception when others then denied:=true;end;if not denied then raise exception 'FAIL professional can access finance';end if;
 perform set_config('request.jwt.claim.sub',uid::text,true);
 perform public.agenda_finance('void',jsonb_build_object('tenant_id',ta,'id',eid,'version',1));
 if (select voided_at from public.financial_entries where id=eid) is null then raise exception 'FAIL void history';end if;
 x:=public.agenda_finance('get',jsonb_build_object('tenant_id',ta,'from',today,'to',today));if jsonb_array_length(x->'appointments')<>1 then raise exception 'FAIL void does not reopen receivable';end if;
 x:=public.agenda_finance('save',jsonb_build_object('tenant_id',ta,'kind','expense','description','Material de teste','category','Materiais','amount',12.25,'due_on',today));eid:=(x->>'id')::uuid;
 perform public.agenda_finance('settle',jsonb_build_object('tenant_id',ta,'id',eid,'version',1,'settled_on',today,'payment_method','Dinheiro'));
 denied:=false;begin perform public.agenda_finance('void',jsonb_build_object('tenant_id',ta,'id',eid,'version',1));exception when others then denied:=true;end;if not denied then raise exception 'FAIL stale version overwrite';end if;
 denied:=false;begin perform public.agenda_finance('save',jsonb_build_object('tenant_id',ta,'kind','expense','description','Invalid fixture','category','Teste','amount',0,'due_on',today));exception when others then denied:=true;end;if not denied then raise exception 'FAIL invalid amount';end if;
 denied:=false;begin perform public.agenda_finance('save',jsonb_build_object('tenant_id',ta,'kind','expense','description','Invalid fixture','category','Teste','amount',10,'due_on',today,'settled_on',today+1,'payment_method','Pix'));exception when others then denied:=true;end;if not denied then raise exception 'FAIL future payment';end if;
 update public.tenants set status='suspended' where id=ta;
 denied:=false;begin perform public.agenda_finance('get',jsonb_build_object('tenant_id',ta,'from',today,'to',today));exception when others then denied:=true;end;if not denied then raise exception 'FAIL suspended company';end if;
 if has_table_privilege('anon','public.financial_entries','SELECT') or has_table_privilege('authenticated','public.financial_entries','SELECT') or has_function_privilege('anon','public.agenda_finance(text,jsonb)','EXECUTE') then raise exception 'FAIL exposed finance';end if;
 if not exists(select 1 from public.audit_logs where tenant_id=ta and action like 'finance:settle%') then raise exception 'FAIL missing audit';end if;
end $$;
select 'PASS: server amounts, persistence, deduplication, tenant isolation, professional denial, suspended license denial, optimistic updates, payment validation, audit and restricted grants' as result;
rollback;
